  { n: 2, tiFact: "corpTIThrough3Months", factor: { num: "4", den: "1" }, pct: { num: "50", den: "100" }, periodLabel: "first 3 months \xD74, 50%" },
  { n: 3, tiFact: "corpTIThrough6Months", factor: { num: "2", den: "1" }, pct: { num: "75", den: "100" }, periodLabel: "first 6 months \xD72, 75%" },
  { n: 4, tiFact: "corpTIThrough9Months", factor: { num: "4", den: "3" }, pct: { num: "100", den: "100" }, periodLabel: "first 9 months \xD74/3, 100%" }
