// ../corpus-us-federal/dist/rules/investment-taxes.js
var fact26 = (factId) => ({ kind: "fact", factId });
var money23 = (cents2) => ({ kind: "money", cents: cents2 });
var ruleRef21 = (ruleId) => ({ kind: "rule", ruleId });
var FROM11 = { effectiveFrom: "2025-01-01" };
