      // $11,200
      dependentExemption: { value: "100000", type: "money" },
      // $1,000
      nysEicPctOfFederal: { value: "30", type: "int" },
      esccPerChildUnder4: { value: "100000", type: "money" },
      // $1,000 (2025)
      esccPerChild4to16: { value: "33000", type: "money" },
      // $330 (2025; $500 for 2026-27)
      esccReductionPer1000: { value: "1650", type: "money" },
      // $16.50
      esccThresholdJoint: { value: "11000000", type: "money" },
      // $110,000
      esccThresholdSingleHohQss: { value: "7500000", type: "money" },
      // $75,000
