checkCmd.requiredOption("--expect <dollars>", "the claimed amount to verify (negative = refund)").option("--tolerance <dollars>", "allowed absolute difference", "1").option("--as-of <date>", "evaluate rules as of this ISO date (default: today)").option("--target <ruleId>", "rule to check (default: net tax; balance due if --withheld)").option("--proof <file>", "write the proof artifact JSON to this file").option("--json", "machine-readable verdict").action((flags) => {
  process.exitCode = runCheck(flags);
});
program2.command("facts").description("list every input fact the corpus understands").option("--json", "machine-readable output").action((flags) => {
  process.exitCode = runFacts({ json: flags.json });
});
program2.command("flags").description("the full grouped catalog of situation flags for eval/check/sweep/\u2026").action(() => {
  const order = [
    "Filing & family:",
    "Income:",
    "Deductions & savings:",
    "Education credits:",
    "Business owner:",
    "Investor (AMT / QSBS):",
    "Corporate & entity (Form 1120):",
    "Payments & estimated tax:",
    "Expert:"
  ];
  console.log();
  for (const group of order) {
    const flags = FACT_FLAGS.filter((f) => f.group === group);
    if (!flags.length)
      continue;
    console.log(`\x1B[1m${group}\x1B[0m`);
    const width = Math.max(...flags.map((f) => f.option.length)) + 2;
    for (const f of flags)
      console.log(`  ${f.option.padEnd(width)}${f.help}`);
    console.log();
  }
  console.log("All of these work on eval, check, sweep, marginal, cliffs, and compare.");
});
program2.command("lookup").description("find the dollar amounts and citations behind a question, e.g. `opentax lookup standard deduction`").argument("<query...>", "plain-English search terms").option("--as-of <date>", "law in force on this ISO date (default: today)").option("--expect <dollars>", "fact-check a claimed amount: exits 0 verified, 1 refuted, 3 unknown").option("--filing-status <status>", "single | mfj | mfs | hoh | qss (narrows --expect to one status)").option("--json", "machine-readable output").action((queryWords, flags) => {
  process.exitCode = runLookup(queryWords, {
    asOf: flags.asOf,
    json: flags.json,
    expect: flags.expect,
    filingStatus: flags.filingStatus
  });
});
program2.command("search").description('full-text search over the encoded law, e.g. `opentax search kiddie tax` \u2014 zero hits means "outside the corpus"').argument("<query...>", "plain-English search terms").option("--as-of <date>", "law in force on this ISO date (default: today)").option("--limit <n>", "max results (default 8)").option("--json", "machine-readable output").action((queryWords, flags) => {
  process.exitCode = runSearch(queryWords, { asOf: flags.asOf, limit: flags.limit, json: flags.json });
});
program2.command("occupation").description("is this a \xA7 224 tipped occupation? matches the Treasury list, never guesses").argument("<title...>", "job title, e.g. `opentax occupation bartender`").option("--json", "machine-readable output").action((words, flags) => {
  process.exitCode = runOccupation(words, { json: flags.json });
});
program2.command("state").description("compose a state return (IL-1040, VA 760, CA 540, NY IT-201, PA-40, NJ-1040, OH IT 1040, NC D-400, GA 500, MD 502, MO-1040, WI Form 1, MN M1) from a composer-facts JSON file").requiredOption("--facts <file>", "composer facts JSON (same shape as the MCP compute_state_return tool)").option("--as-of <date>", "law in force on this ISO date (default: today)").option("--json", "machine-readable output").action((flags) => {
  process.exitCode = runState({ facts: flags.facts, asOf: flags.asOf, json: flags.json });
});
program2.command("signup").description("get OpenTax updates by email (new features and other things worth knowing)").argument("<email>", "your email address").option("--json", "machine-readable output").action(async (email, flags) => {
  process.exitCode = await runSignup(email, { json: flags.json });
});
program2.command("verify").description("re-execute a proof artifact and confirm or refute it").argument("<proof>", "proof artifact JSON file").option("--json", "machine-readable output").action((proofPath, flags) => {
  process.exitCode = runVerify(proofPath, { json: flags.json });
});
program2.command("explain").description("show a rule: citation, effective window, parameters, dependencies").argument("<ruleId>", "rule id, e.g. us.federal.standard_deduction").option("--as-of <date>", "only the version valid on this date").option("--json", "machine-readable output").action((ruleId, flags) => {
  process.exitCode = runExplain(ruleId, { asOf: flags.asOf, json: flags.json });
});
function solverCommand(name, description) {
  const cmd = program2.command(name).description(description);
  cmd.option("--facts <file>", "JSON facts file (inline flags below override it)");
  registerFactFlags(cmd);
  cmd.option("--vary <factId>", "fact to vary", "wages").option("--as-of <date>", "evaluate rules as of this ISO date (default: today)").option("--target <ruleId>", "rule to derive (default: net tax)").option("--json", "machine-readable output");
  return cmd;
}
solverCommand("sweep", "evaluate the target across a range of one input").requiredOption("--from <dollars>", "range start").requiredOption("--to <dollars>", "range end").option("--step <dollars>", "step size", "1000").option("--csv", "CSV output").action((flags) => {
  process.exitCode = runSweep(flags);
});
solverCommand("marginal", "effective marginal rate at a point").requiredOption("--at <dollars>", "input value to differentiate at").option("--delta <dollars>", "finite-difference increment", "100").action((flags) => {
  process.exitCode = runMarginal(flags);
});
solverCommand("cliffs", "find exact dollars where one more cent of input costs more than a cent (marginal > 100%)").requiredOption("--from <dollars>", "range start").requiredOption("--to <dollars>", "range end").option("--step <dollars>", "coarse scan step", "1000").action((flags) => {
  process.exitCode = runCliffs(flags);
});
solverCommand("invert", "smallest input where the target first reaches a goal (e.g. wages that produce a given tax)").requiredOption("--goal <dollars>", "target value to reach").requiredOption("--lo <dollars>", "search range start").requiredOption("--hi <dollars>", "search range end").action((flags) => {
  process.exitCode = runInvert(flags);
});
solverCommand("compare", "compare the answer across an enum fact's values").action((flags) => {
  process.exitCode = runCompare({ ...flags, vary: flags.vary === "wages" ? "filingStatus" : flags.vary });
});
var corpusCmd = program2.command("corpus").description("inspect the installed rule corpus");
corpusCmd.command("hash").description("print the corpus Merkle root").option("--json", "machine-readable output").action((flags) => {
  process.exitCode = runCorpusHash({ json: flags.json });
});
corpusCmd.command("export").description("full corpus as JSON, for independent verifiers (see kernel/)").action(() => {
  process.exitCode = runCorpusExport();
});
corpusCmd.command("list").description("list rules with validity windows and citations").option("--as-of <date>", "only rules valid on this date").option("--json", "machine-readable output").action((flags) => {
  process.exitCode = runCorpusList({ asOf: flags.asOf, json: flags.json });
});
function runCli(argv) {
  program2.parse(argv);
}

// dist/bin.js
runCli();
